import { mkdir } from 'node:fs/promises';
import { join } from 'node:path';
// Portable, deterministic WAV fixture; production demo is generated by Rust.
await mkdir('fixtures', { recursive: true });
for (const [name, rate] of [
  ['tone-44100', 44100],
  ['tone-48000', 48000],
] as const) {
  const frames = rate * 5;
  const b = Buffer.alloc(44 + frames * 4);
  b.write('RIFF');
  b.writeUInt32LE(b.length - 8, 4);
  b.write('WAVEfmt ', 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(2, 22);
  b.writeUInt32LE(rate, 24);
  b.writeUInt32LE(rate * 4, 28);
  b.writeUInt16LE(4, 32);
  b.writeUInt16LE(16, 34);
  b.write('data', 36);
  b.writeUInt32LE(frames * 4, 40);
  for (let i = 0; i < frames; i++) {
    const t = i / rate;
    const fade = Math.min(1, t * 50, (5 - t) * 50);
    const value = Math.round(Math.sin(t * Math.PI * 2 * 220) * 6000 * fade);
    b.writeInt16LE(value, 44 + i * 4);
    b.writeInt16LE(value, 46 + i * 4);
  }
  await Bun.write(join('fixtures', `${name}.wav`), b);
}
console.log('WAV fixtures generated in fixtures/. Import with the native file picker.');
